type Request = (operation:string,input:Record<string,unknown>,signal:AbortSignal)=>Promise<any>;
/** Explicit authenticated GM browser decisions, independent of provider credentials. */
export class ForestBattlemapPanel {
  private readonly cancellation=new AbortController();
  private packageId='';private digest='';private approvalId='';
  constructor(private readonly host:HTMLElement,private readonly request:Request) {}
  cancel(){this.cancellation.abort();}
  open() {
    this.host.hidden=false;this.host.replaceChildren();
    const title=document.createElement('h3');title.textContent='Forest test map';
    const explanation=document.createElement('p');explanation.textContent='Review forest artwork in test mcp using the previous approved fixture or a recorded new image handoff. These controls send no image or model requests. Create an inactive scene; choose GM preview or TV calibration explicitly.';
    const status=document.createElement('p');status.setAttribute('role','status');
    const review=document.createElement('pre');review.style.whiteSpace='pre-wrap';
    const profile=document.createElement('select');profile.setAttribute('aria-label','Forest map preview');
    for(const [value,label] of [['gm-preview','GM preview (no TV acceptance)'],['tv','Authenticated TV viewport']]){const option=document.createElement('option');option.value=value!;option.textContent=label!;profile.append(option);}
    const action=(label:string,work:()=>Promise<void>)=>{const button=document.createElement('button');button.type='button';button.textContent=label;button.addEventListener('click',()=>{button.disabled=true;void work().catch((error:unknown)=>{status.textContent=error instanceof Error?error.message:'Forest workflow unavailable. Reconnect and inspect receipts before retrying an uncertain apply.';}).finally(()=>{button.disabled=false;});});return button;};
    const generationId=document.createElement('input');generationId.type='text';generationId.maxLength=64;generationId.placeholder='New image request ID from this conversation';generationId.setAttribute('aria-label','New forest image request ID');
    const reset=()=>{this.packageId='';this.digest='';this.approvalId='';review.textContent='';};
    generationId.addEventListener('input',reset);
    const input=()=>{const id=generationId.value.trim();if(id&&!/^[a-f0-9]{64}$/.test(id))throw Error('Enter the exact new image request ID.');return {worldId:'mcp-test',...(id?{generationId:id}:{})};};
    const generationStatus=action('Check new image handoff',async()=>{if(!generationId.value.trim())throw Error('Enter the new image request ID first.');const result=await this.request('battlemap-generation-status',input(),this.cancellation.signal);review.textContent=JSON.stringify(result,null,2);status.textContent=`New image request: ${result.name}; ${result.status}. Secure manual generation handoff; automatic generation is unavailable.`;});
    const generationComplete=action('Import securely staged new image',async()=>{if(!generationId.value.trim())throw Error('Enter the new image request ID first.');const result=await this.request('battlemap-generation-complete',input(),this.cancellation.signal);reset();review.textContent=JSON.stringify(result,null,2);status.textContent=`New artwork imported for ${result.fixture.name}. No scene created; TV calibration and physical measurement remain pending.`;});
    const thread=action('Initialize a fresh forest conversation',async()=>{const result=await this.request('battlemap-thread',input(),this.cancellation.signal);review.textContent=JSON.stringify(result,null,2);status.textContent='Fresh private conversation initialized without inference. Configure its approved startup budget before submitting a prompt.';});
    const budget=action('Use configured forest test budget',async()=>{const result=await this.request('battlemap-acceptance',input(),this.cancellation.signal);review.textContent=JSON.stringify(result,null,2);status.textContent=`Forest test budget bound: ${result.maxModelRequests} total requests within this binding. No model request sent. Test consumption persists across reconnects; normal chat requires no test allowance.`;});
    const imported=action('Import approved forest artwork',async()=>{const result=await this.request('battlemap-import',input(),this.cancellation.signal);status.textContent=`Artwork ${result.status}. No scene created.`;});
    const prepare=action('Prepare forest scene review',async()=>{const result=await this.request('battlemap-prepare',{...input(),profile:profile.value},this.cancellation.signal);this.packageId=result.package.id;this.digest=result.package.digest;this.approvalId='';review.textContent=JSON.stringify({profile:result.profile,physicalAcceptance:false,scene:result.package.sceneRequest.args.data,reviewDigest:this.digest},null,2);status.textContent='Exact scene prepared. Review the background, dimensions, native level and grid before applying.';});
    const approve=action('Approve this exact forest scene',async()=>{if(!this.packageId||!this.digest)throw Error('Prepare first');const result=await this.request('battlemap-review',{...input(),packageId:this.packageId,reviewDigest:this.digest},this.cancellation.signal);this.approvalId=result.approvalId;status.textContent='Exact native scene review approved. Scene has not been created yet.';});
    const apply=action('Create reviewed forest scene',async()=>{if(!this.approvalId)throw Error('Review first');const result=await this.request('battlemap-apply',{...input(),packageId:this.packageId,approvalId:this.approvalId},this.cancellation.signal);review.textContent=JSON.stringify(result,null,2);status.textContent=`Inactive forest scene created and read back: ${result.result.sceneId}. View it in Scenes. Physical TV acceptance remains pending.`;});
    const refresh=action('Check forest scene receipt',async()=>{if(!this.packageId)throw Error('Prepare first');const result=await this.request('battlemap-status',{...input(),packageId:this.packageId},this.cancellation.signal);review.textContent=JSON.stringify(result,null,2);status.textContent='Receipt refreshed; no scene mutation or model request.';});
    const display=action('Display reviewed forest scene',async()=>{if(!this.packageId)throw Error('Prepare first');const result=await this.request('battlemap-display',{...input(),packageId:this.packageId},this.cancellation.signal);review.textContent=JSON.stringify(result,null,2);status.textContent=result.profile==='tv'?'Actual TV scene and Digital Tabletop viewport acknowledged. Measure a grid square with a ruler before accepting one-inch scale.':'GM preview acknowledged; physical TV acceptance remains pending.';});
    profile.addEventListener('change',()=>{this.packageId='';this.digest='';this.approvalId='';review.textContent='';});
    const handoffExplanation=document.createElement('p');handoffExplanation.textContent='For a new image, ask in the current conversation, enter its request ID here, and check the recorded handoff. A trusted operator must generate and securely stage one matching new image before import. Keep the request ID selected for scene review and creation. Clearing it selects the previous fixture.';
    this.host.append(title,explanation,profile,thread,budget,handoffExplanation,generationId,generationStatus,generationComplete,imported,prepare,approve,apply,refresh,display,status,review);
  }
}
